solution.solution.cpp:
#include <utility>

namespace lib
{
    inline int openCount{ 0 };
    inline int nextId{ 1 };
    inline int open() { ++openCount; return nextId++; }
    inline void close(int id) { if (id > 0) --openCount; }
}

class Resource
{
public:
    Resource() : handle{ lib::open() } {}
    ~Resource() { lib::close(handle); }
    Resource(const Resource&) = delete;
    Resource& operator=(const Resource&) = delete;
    int id() const { return handle; }

private:
    int handle;
};

template <typename F>
class ScopeExit
{
public:
    explicit ScopeExit(F action) : action{ std::move(action) } {}
    ~ScopeExit() { if (active) action(); }
    ScopeExit(const ScopeExit&) = delete;
    ScopeExit& operator=(const ScopeExit&) = delete;
    void dismiss() { active = false; }

private:
    F action;
    bool active{ true };
};

unitTests:
#include <stdexcept>
static int useTwo(bool bailOut)
{
    Resource a;
    Resource b;
    if (bailOut) return -1;
    return a.id() + b.id();
}
static void throwWithOne() { Resource r; throw std::runtime_error("load failed"); }

TEST("closed at the end of a scope") {
    const int before{ lib::openCount };
    {
        Resource r;
        CHECK(r.id() > 0);
        CHECK_EQ(lib::openCount, before + 1);
    }
    CHECK_EQ(lib::openCount, before);
}
TEST("closed on early return and on exceptions") {
    const int before{ lib::openCount };
    useTwo(true);
    CHECK_EQ(lib::openCount, before);
    useTwo(false);
    CHECK_EQ(lib::openCount, before);
    try { throwWithOne(); } catch (const std::exception&) {}
    CHECK_EQ(lib::openCount, before);
}
TEST("each resource has its own id") {
    Resource a, b;
    CHECK(a.id() != b.id());
}
TEST("scope guards run, unless dismissed") {
    int log{ 0 };
    { ScopeExit g{ [&] { log += 1; } }; CHECK_EQ(log, 0); }
    CHECK_EQ(log, 1);
    { ScopeExit g{ [&] { log += 10; } }; g.dismiss(); }
    CHECK_EQ(log, 1);
    try { ScopeExit g{ [&] { log += 100; } }; throw 5; } catch (int) {}
    CHECK_EQ(log, 101);
}

